"use client";

/**
 * Label: the visible name of a form control.
 * Purpose: wraps Radix Label, so clicking the label focuses its control. Generated by shadcn, then
 *   re-themed to Grove. Owner: design system. FormField (S2-T05) places it with the hint and error.
 * Props: required (shows a red asterisk; also set `required` or aria-required on the control),
 *   optionalLabel (already-translated "(optional)", shown quieter after the text), htmlFor and
 *   every Radix Label prop.
 * Responsive: none. Accessibility: every control has a label; placeholders are not labels. The
 *   asterisk is hidden from screen readers because the control itself announces "required".
 * States: none. Dependencies: radix Label, cn. Tests: inputs.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .label).
 */
import { Label as LabelPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

type LabelProps = ComponentProps<typeof LabelPrimitive.Root> & {
  required?: boolean | undefined;
  optionalLabel?: string | undefined;
};

function Label({ className, required, optionalLabel, children, ...props }: LabelProps) {
  return (
    <LabelPrimitive.Root
      data-slot="label"
      className={cn("text-small font-semibold text-ink select-none", className)}
      {...props}
    >
      {children}
      {required ? (
        <span aria-hidden="true" className="ml-1 text-danger">
          *
        </span>
      ) : null}
      {optionalLabel ? <span className="ml-1 font-normal text-muted">{optionalLabel}</span> : null}
    </LabelPrimitive.Root>
  );
}

export { Label };
